def init_db():
    return True

def _db_error(action, exc):
    st.error(f"Could not {action}. Please check the Supabase connection and table configuration.")
    st.caption(f"Details: {exc}")

def insert_record(table, data):
    try: return supabase.table(table).insert(data).execute().data or []
    except Exception as exc: _db_error("save this record", exc); return []

def upsert_record(table, data, on_conflict):
    try: return supabase.table(table).upsert(data, on_conflict=on_conflict).execute().data or []
    except Exception as exc: _db_error("save these settings", exc); return []

def delete_record(table, record_id):
    try: return supabase.table(table).delete().eq("id", record_id).execute().data or []
    except Exception as exc: _db_error("delete this record", exc); return []

def update_record(table, record_id, data):
    try: return supabase.table(table).update(data).eq("id", record_id).execute().data or []
    except Exception as exc: _db_error("update this record", exc); return []

def fetch_df(table, filters=None, columns="*", order_by=None, descending=False):
    try:
        query=supabase.table(table).select(columns)
        for key,value in (filters or {}).items(): query=query.eq(key,value)
        if order_by: query=query.order(order_by, desc=descending)
        df = pd.DataFrame(query.execute().data or [])
        df.attrs["load_failed"] = False
        return df
    except Exception as exc:
        _db_error("load the records", exc)
        df = pd.DataFrame()
        df.attrs["load_failed"] = True
        return df


def load_failed(df):
    return bool(getattr(df, "attrs", {}).get("load_failed", False))

_MIME_BY_EXT = {
    "doc": "application/msword",
    "docx": "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
    "xls": "application/vnd.ms-excel",
    "xlsx": "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
    "ppt": "application/vnd.ms-powerpoint",
    "pptx": "application/vnd.openxmlformats-officedocument.presentationml.presentation",
    "pdf": "application/pdf",
    "txt": "text/plain",
    "csv": "text/csv",
    "zip": "application/zip",
    "rar": "application/vnd.rar",
    "7z": "application/x-7z-compressed",
    "mp4": "video/mp4",
    "webm": "video/webm",
    "mov": "video/quicktime",
    "m4v": "video/x-m4v",
    "mp3": "audio/mpeg",
    "wav": "audio/wav",
    "png": "image/png",
    "jpg": "image/jpeg",
    "jpeg": "image/jpeg",
    "gif": "image/gif",
    "webp": "image/webp",
    "bmp": "image/bmp",
    "svg": "image/svg+xml",
}

def _file_mime_type(filename, browser_type=None):
    ext = PurePosixPath(str(filename)).suffix.lower().lstrip(".")
    return _MIME_BY_EXT.get(ext) or browser_type or mimetypes.guess_type(str(filename))[0] or "application/octet-stream"

def upload_to_storage(uploaded_file, school_year, semester):
    """Upload using an ASCII-only object key; preserve original filename/type in metadata."""
    if uploaded_file is None:
        return None
    try:
        year = school_year.replace("/", "-")
        sem = semester.replace(" ", "-")
        original_name = PurePosixPath(uploaded_file.name).name
        ext = PurePosixPath(original_name).suffix.lower()
        mime_type = _file_mime_type(original_name, getattr(uploaded_file, "type", None))
        object_name = f"{uuid.uuid4().hex}{ext}"
        path = f"{year}/{sem}/{object_name}"
        storage_supabase.storage.from_("school-files").upload(
            path, uploaded_file.getvalue(),
            {"content-type": mime_type, "upsert": False}
        )
        public_url = storage_supabase.storage.from_("school-files").get_public_url(path)
        return {"url": str(public_url), "name": original_name, "mime": mime_type, "extension": ext.lstrip(".")}
    except Exception as exc:
        _db_error(f"upload '{getattr(uploaded_file, 'name', 'attachment')}'", exc)
        return None

def _storage_object_path_from_url(url):
    """Return our school-files object path from a Supabase public URL, otherwise None."""
    raw = str(url or "").split("?", 1)[0]
    markers = [
        "/storage/v1/object/public/school-files/",
        "/storage/v1/object/sign/school-files/",
    ]
    for marker in markers:
        if marker in raw:
            return raw.split(marker, 1)[1]
    return None


def _delete_storage_records(value):
    """Best-effort cleanup for files owned by the school-files bucket."""
    if value is None:
        return
    raw = str(value or "")
    if ATTACHMENT_TEXT_MARKER in raw:
        _, raw = raw.split(ATTACHMENT_TEXT_MARKER, 1)
    records = _parse_attachment_records(raw)
    paths = []
    for record in records:
        path = _storage_object_path_from_url(record.get("url"))
        if path:
            paths.append(path)
    if not paths:
        return
    try:
        storage_supabase.storage.from_("school-files").remove(paths)
    except Exception:
        # Database deletion must not fail only because storage cleanup failed.
        pass


def upload_many_to_storage(uploaded_files, school_year, semester):
    """Upload all selected files atomically from the UI perspective.

    Returns JSON metadata on success, an empty string when no files were selected,
    and None if any selected file failed. Successfully uploaded files are cleaned
    up when another file in the same batch fails.
    """
    files = list(uploaded_files or [])
    if not files:
        return ""

    records = []
    for uploaded_file in files:
        record = upload_to_storage(uploaded_file, school_year, semester)
        if not record:
            for uploaded_record in records:
                _delete_storage_records(json.dumps([uploaded_record], ensure_ascii=False))
            st.error("One or more attachments could not be uploaded. The record was not saved.")
            return None
        records.append(record)
    return json.dumps(records, ensure_ascii=False)

def _attachment_type(url):
    clean = str(url).split("?")[0].lower()
    filename = clean.rstrip("/").split("/")[-1]
    ext = filename.rsplit(".", 1)[-1] if "." in filename else ""
    if ext in {"png","jpg","jpeg","gif","webp","bmp","svg"}: return "image", ext
    if ext in {"mp4","webm","mov","m4v","avi","mkv"}: return "video", ext
    if ext == "pdf": return "pdf", ext
    if ext in {"doc","docx","xls","xlsx","ppt","pptx"}: return "office", ext
    return "file", ext


def _attachment_icon(kind):
    return {"image":"🖼️", "video":"🎬", "pdf":"📕", "office":"📄", "file":"📎"}.get(kind, "📎")


def _parse_attachment_records(value):
    """Read new JSON attachment metadata and remain compatible with old URL-only values."""
    if value is None or not str(value).strip():
        return []
    raw = str(value).strip()
    try:
        parsed = json.loads(raw)
        if isinstance(parsed, dict):
            parsed = [parsed]
        if isinstance(parsed, list) and all(isinstance(x, dict) and x.get("url") for x in parsed):
            return parsed
    except Exception:
        pass
    return [{"url": x.strip()} for x in raw.replace(";", "\n").splitlines() if x.strip()]


ATTACHMENT_TEXT_MARKER = "\n\n__PORTAL_ATTACHMENTS__::"

def pack_text_with_attachments(text, attachment_json):
    """Keep attachments inside an existing text column so no DB schema change is required."""
    clean = str(text or "").strip()
    if not attachment_json:
        return clean
    return clean + ATTACHMENT_TEXT_MARKER + str(attachment_json)

def unpack_text_with_attachments(value):
    """Return clean text plus attachment metadata stored in a text field."""
    raw = str(value or "")
    if ATTACHMENT_TEXT_MARKER not in raw:
        return raw, ""
    clean, blob = raw.split(ATTACHMENT_TEXT_MARKER, 1)
    return clean.rstrip(), blob.strip()

def render_text_and_attachments(value, label="Attachments"):
    clean_text, attachment_blob = unpack_text_with_attachments(value)
    if clean_text:
        st.write(clean_text)
    render_attachment_links(attachment_blob, label)

def render_attachment_links(value, label="Attachments"):
    """Show attachments as visible cards, with previews for images/videos/PDFs."""
    records = _parse_attachment_records(value)
    if not records:
        return
    st.markdown(f"### 📎 {label}")
    for start in range(0, len(records), 2):
        cols = st.columns(2, gap="medium")
        for col, record in zip(cols, records[start:start+2]):
            with col:
                url = str(record.get("url") or "").strip()
                if not url:
                    continue
                filename = str(record.get("name") or "").strip() or url.split("?")[0].rstrip("/").split("/")[-1].replace("%20", " ") or "Attachment"
                mime_type = str(record.get("mime") or "").lower()
                ext = str(record.get("extension") or PurePosixPath(filename).suffix.lstrip(".")).lower()
                if mime_type.startswith("image/") or ext in {"png","jpg","jpeg","gif","webp","bmp","svg"}:
                    kind = "image"
                elif mime_type.startswith("video/") or ext in {"mp4","webm","mov","m4v","avi","mkv"}:
                    kind = "video"
                elif mime_type == "application/pdf" or ext == "pdf":
                    kind = "pdf"
                elif mime_type.startswith("application/vnd.") or ext in {"doc","docx","xls","xlsx","ppt","pptx"}:
                    kind = "office"
                else:
                    kind = "file"
                icon = _attachment_icon(kind)
                st.markdown(f"<div class='attachment-card'><div class='attachment-card-title'>{icon} {filename}</div></div>", unsafe_allow_html=True)
                try:
                    if kind == "image":
                        st.image(url, use_container_width=True)
                    elif kind == "video":
                        st.video(url)
                    elif kind == "pdf":
                        st.markdown(f"<iframe src='{url}' width='100%' height='360' style='border:1px solid #d9e1e8;border-radius:12px;background:#fff;'></iframe>", unsafe_allow_html=True)
                    else:
                        st.markdown(f"<div class='attachment-file-preview'><div class='attachment-big-icon'>{icon}</div><div>{ext.upper() or 'FILE'}</div><small>File ready to open/share</small></div>", unsafe_allow_html=True)
                except Exception:
                    st.info("Preview is not available for this file type.")
                if url.startswith(("http://", "https://")):
                    st.markdown(f"<a class='attachment-open' href='{url}' target='_blank' rel='noopener noreferrer'>🔗 Open / Share</a>", unsafe_allow_html=True)


