def _make_admin_token():
    # Signed short-lived session token: one login remains valid while navigating.
    expires = int(time.time()) + ADMIN_SESSION_TTL
    nonce = secrets.token_urlsafe(18)
    payload = f"{expires}:{nonce}"
    signature = hmac.new(ADMIN_SESSION_SECRET, payload.encode("utf-8"), digestmod="sha256").hexdigest()
    return f"{payload}.{signature}"

def _valid_admin_token(token):
    if not token or "." not in str(token):
        return False
    payload, signature = str(token).split(".", 1)
    if ":" not in payload:
        return False
    expires_text, _nonce = payload.split(":", 1)
    try:
        expires = int(expires_text)
    except ValueError:
        return False
    if expires <= int(time.time()):
        return False
    expected = hmac.new(ADMIN_SESSION_SECRET, payload.encode("utf-8"), digestmod="sha256").hexdigest()
    return hmac.compare_digest(signature, expected)

def render_auth():
    # Keep the administrator authenticated while moving between all pages.
    # The signed token is independent of Streamlit's in-memory session state.
    token = st.query_params.get("admin_token")
    if token and _valid_admin_token(token):
        st.session_state.admin_mode = True
        st.session_state.admin_session_token = str(token)

    if "admin_mode" not in st.session_state:
        st.session_state.admin_mode = False

    if not st.session_state.admin_mode:
        with st.expander("🔐 Administrator Access", expanded=False):
            password = st.text_input(
                "Admin Password",
                type="password",
                key="admin_password",
            )
            if st.button("Unlock Editing", use_container_width=True):
                stored_password = str(ADMIN_PASSWORD).strip()
                entered_password = str(password).strip()

                if hmac.compare_digest(entered_password, stored_password):
                    token = _make_admin_token()
                    st.session_state.admin_mode = True
                    st.session_state.admin_session_token = token
                    st.query_params["admin_token"] = token
                    st.rerun()
                else:
                    st.error("Incorrect password.")
    else:
        st.success("🔓 Administrator editing mode")
        if st.button("Lock / Viewer Mode"):
            st.session_state.admin_mode = False
            st.session_state.pop("admin_session_token", None)
            if "admin_token" in st.query_params:
                del st.query_params["admin_token"]
            st.rerun()

def get_current_page():
    allowed={"Home","Semester Plan","Demo Lessons","Supervisory Visits","Professional Development","Peer Visits","Educational Initiatives","Professional Learning Community","Files & Archive","Files"}
    page=st.query_params.get("page","Home")
    return page if page in allowed else "Home"

def navigate_to(page):
    # Change only the page parameter; preserve the admin session token.
    token = st.query_params.get("admin_token")
    st.query_params["page"] = page
    if token:
        st.query_params["admin_token"] = token
    st.rerun()

def portal_toolbar(semester, page):
    c1,c2,c3=st.columns([1.25,1.25,2.2])
    with c1:
        semester=st.selectbox("Semester",SEMESTERS,index=SEMESTERS.index(semester) if semester in SEMESTERS else 0,key="top_semester",label_visibility="collapsed")
    with c2:
        if page!="Home":
            if st.button("⌂  Back to Home",use_container_width=True): navigate_to("Home")
    with c3:
        render_auth()
    return semester

def can_edit():
    return st.session_state.get("admin_mode", False)


