def show_table(df):
    if df.empty and not load_failed(df):
        st.info("No records found.")
        return
    st.dataframe(df, use_container_width=True, hide_index=True)


def render_platform_comments(school_year, semester):
    """Public feedback area for comments about the platform as a whole."""
    st.markdown("---")
    st.subheader("💬 Visitor Comments")
    st.caption("We welcome your feedback about the Senior Teacher Platform as a whole.")

    with st.form("visitor_comment_form", clear_on_submit=True):
        visitor_name = st.text_input("Name (optional)", max_chars=80, placeholder="Your name")
        comment = st.text_area(
            "Your comment",
            max_chars=1000,
            height=120,
            placeholder="Share your feedback, suggestion, or appreciation...",
        )
        submitted = st.form_submit_button(
            "💬 Post Comment", type="primary", use_container_width=True
        )

    if submitted:
        clean_comment = comment.strip()
        clean_name = visitor_name.strip() or "Visitor"

        if not clean_comment:
            st.warning("Please enter a comment before posting.")
        else:
            # Use the existing Supabase table: site_comments.
            # Some existing projects use "visitor_name", while older versions
            # may use "name", so try the current field first and fall back safely.
            saved = False
            try:
                result = (
                    supabase.table("site_comments")
                    .insert({
                        "visitor_name": clean_name,
                        "comment": clean_comment,
                    })
                    .execute()
                )
                saved = bool(result.data)
            except Exception as exc:
                try:
                    result = (
                        supabase.table("site_comments")
                        .insert({
                            "name": clean_name,
                            "comment": clean_comment,
                        })
                        .execute()
                    )
                    saved = bool(result.data)
                except Exception as exc2:
                    _db_error("save this comment", exc2)

            if saved:
                st.success("Thank you! Your comment has been posted.")
                st.rerun()

    # Comments are global: they are about the platform as a whole,
    # not about a particular school year or semester.
    comments = fetch_df("site_comments")

    if not comments.empty:
        if "created_at" in comments.columns:
            comments = comments.sort_values("created_at", ascending=False)
        comments = comments.head(20)

    if comments.empty and not load_failed(comments):
        st.info("No comments yet. Be the first to share your feedback!")
    else:
        for _, row in comments.iterrows():
            name = row.get("visitor_name")
            if name is None or str(name).strip() == "":
                name = row.get("name")
            name = str(name or "Visitor")
            text = str(row.get("comment") or "")
            created = row.get("created_at")
            when = str(created)[:16].replace("T", " ") if created else ""

            with st.container(border=True):
                st.markdown(f"**💬 {name}**")
                if when:
                    st.caption(when)
                st.write(text)

    admin_global_comments()


def admin_global_comments():
    """Admin management for global visitor comments in site_comments."""
    if not can_edit():
        return

    st.markdown("---")
    st.subheader("⚙️ Manage Visitor Comments")

    df = fetch_df("site_comments")
    if df.empty:
        if not load_failed(df):
            st.caption("No comments available to manage.")
        return

    if "id" not in df.columns:
        st.caption("The site_comments table must contain an id column for management.")
        return

    if "created_at" in df.columns:
        df = df.sort_values("created_at", ascending=False)

    name_col = "visitor_name" if "visitor_name" in df.columns else (
        "name" if "name" in df.columns else None
    )

    display_columns = []
    if name_col:
        display_columns.append(name_col)
    if "comment" in df.columns:
        display_columns.append("comment")

    if not display_columns:
        st.caption("The site_comments table does not contain the expected comment fields.")
        return

    options = {}
    for _, row in df.iterrows():
        parts = [
            str(row.get(c, ""))
            for c in display_columns
            if row.get(c) is not None and str(row.get(c)).strip()
        ]
        summary = " — ".join(parts)[:150] if parts else "Comment"
        options[f"#{int(row['id'])} — {summary}"] = int(row["id"])

    label = st.selectbox(
        "Select a comment",
        list(options),
        key="manage_select_site_comments",
    )
    selected_id = options[label]
    selected = df[df.id == selected_id].iloc[0]

    with st.form(f"edit_form_site_comments_{selected_id}"):
        edited = {}

        if name_col:
            edited[name_col] = st.text_input(
                "Visitor Name",
                value="" if selected[name_col] is None else str(selected[name_col]),
            )

        if "comment" in df.columns:
            edited["comment"] = st.text_area(
                "Comment",
                value="" if selected["comment"] is None else str(selected["comment"]),
                height=140,
            )

        c1, c2 = st.columns(2)
        with c1:
            save = st.form_submit_button("💾 Save Changes", use_container_width=True)
        with c2:
            delete = st.form_submit_button("🗑️ Delete Comment", use_container_width=True)

    if save and update_record("site_comments", selected_id, edited):
        st.success("Changes saved successfully.")
        st.rerun()

    if delete and delete_record("site_comments", selected_id):
        st.success("Comment deleted successfully.")
        st.rerun()


